SELECT CASE WHEN s.rating >= 4.2 THEN 'high' WHEN s.rating >= 2.5 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(i.last_restock) AS first_last_restock FROM inventory i FULL OUTER JOIN products p ON i.product_id = p.id FULL OUTER JOIN suppliers s ON p.supplier_id = s.id WHERE i.last_restock > '2023-07-01' GROUP BY CASE WHEN s.rating >= 4.2 THEN 'high' WHEN s.rating >= 2.5 THEN 'mid' ELSE 'low' END ORDER BY first_last_restock;
